/** Follow a caller-owned stream only after mount; one queued scroll owns each frame. */
export function useStreamFollow(
  element: Ref<HTMLElement | undefined>,
  enabled: () => boolean,
  reduced: Ref<boolean>,
  changes: WatchSource[],
) {
  let mounted = false;
  let pending: number | undefined;
